        ".cv2-add-pop .cv2-add-result{position:relative;display:flex;align-items:center;gap:11px;padding:8px 9px;border:none!important;background:none!important;box-shadow:none!important;text-shadow:none!important;outline:none!important;border-radius:11px!important;cursor:pointer;text-align:left;width:100%;transition:background .12s;}",
