      const tryLive = () => { if (isClosetUrl() && neutralize(document)) showShell(); };
      if (isClosetUrl()) {
        tryLive();
        if (!window.dtrParkedRoot()) {
          const obs = new MutationObserver(() => { tryLive(); if (window.dtrParkedRoot()) obs.disconnect(); });
          obs.observe(document.documentElement || document, { childList: true, subtree: true });
          document.addEventListener('DOMContentLoaded', tryLive, { once: true });
          setTimeout(() => obs.disconnect(), 8000);
        }
      }

      document.addEventListener('turbo:before-render', (e) => {
        const nb = e.detail && e.detail.newBody;
        if (nb) neutralize(nb);
      });

      ['turbo:render', 'turbo:load'].forEach(ev => document.addEventListener(ev, () => {
        if (!isClosetUrl()) return;
        neutralize(document);
        showShell();
      }));
