        const _clip = (function(){ try { const a = JSON.parse(window.dtrStore.get('dtr:ps:clip', '[]')); return Array.isArray(a) ? a.filter(x => x && x.id).map(x => ({ id: String(x.id) })) : []; } catch (_) { return []; } })();
