          const secGrid = sections.map((sec) => {
            const c2 = secCols(sec);
            return { sec: sec, cols: c2, w: c2 * cellW + (c2 - 1) * gap, rows: Math.ceil(sec.list.length / c2) };
          });
          const colGap = 22;
          const W = pad * 2 + secGrid.reduce((a2, g) => a2 + g.w, 0) + colGap * (secGrid.length - 1);
          const H = 12 + secTitleH + Math.max.apply(null, secGrid.map((g) => g.rows * (cellH + gap))) + footH;
          const cvs = document.createElement('canvas'); cvs.width = Math.round(W * dpr); cvs.height = Math.round(H * dpr);
          const ctx = cvs.getContext('2d'); ctx.scale(dpr, dpr);
