            "#dia-ps-board .dia-psb-split{flex:1;min-height:0;display:flex}",

            "#dia-ps-board .dia-psb-flip{flex:none;align-self:center;margin:0 -14px;z-index:30;width:28px;height:28px;display:inline-flex;align-items:center;justify-content:center;border:1.5px solid var(--dtr-lilac,#ded0e4);border-radius:999px;background:var(--dtr-card,#fff);color:var(--dtr-berry,#c2487c);cursor:pointer;box-shadow:0 2px 8px var(--dtr-shadow-tint,rgba(150,120,160,.14));transition:background .12s,color .12s,transform .12s}",

