            "#dia-ps-board .dia-psb-flip{position:relative}",

            "#dia-ps-board .dia-psb-flip:hover::after{content:attr(aria-label);position:absolute;left:50%;top:calc(100% + 10px);transform:translateX(-50%);white-space:nowrap;background:var(--dtr-ink-strong,#4a4453);color:var(--dtr-onfill,#fff);font:800 10.5px Nunito,Arial,sans-serif;letter-spacing:.02em;padding:7px 11px;border-radius:9px;border:1.5px solid var(--dtr-glass-strong, rgba(255,255,255,.9));pointer-events:none;z-index:40;box-shadow:0 6px 18px -4px rgba(0,0,0,.45)}",
            "#dia-ps-board .dia-psb-flip:hover{background:var(--dtr-pink-pale,#ffe3ec);transform:scale(1.06)}",
