            "#dia-ps-board .dia-psb-col-head{position:sticky;top:0;z-index:14;display:flex;align-items:center;justify-content:center;gap:8px;margin:0 -18px;padding:10px 18px;background:var(--dtr-card, #fff);border-bottom:1px solid var(--dtr-lilac,#ded0e4);backdrop-filter:none;-webkit-backdrop-filter:none;box-shadow:0 6px 12px -10px var(--dtr-shadow-tint,rgba(150,120,160,.42));-dtr-unused:blur(7px);border-radius:0 0 12px 12px;padding:8px 2px}",

