            "#dia-ps-board li.object .name.dia-item-name{display:block;font:600 10.5px/1.32 Nunito,Arial,sans-serif;color:var(--dtr-deep, #2a4a3a);text-align:center;padding:4px 6px 7px;word-break:break-word}",
            "#dia-ps-board li.object .dia-psb-sp2{display:block;font:600 9.5px Nunito,Arial,sans-serif;color:var(--dtr-grey5, #9a9a90);margin-top:2px}",
            "#dia-ps-board li.object .dia-psb-note2{font:600 9px Nunito,Arial,sans-serif;color:var(--dtr-primary,#149c8e);background:var(--dtr-primary-bg,#e7f6f2);border-radius:6px;padding:2px 7px;margin:0 6px 7px;max-width:calc(100% - 12px);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;align-self:center}",

