            "#dia-ps-board li.object:hover .cv2-qty-val{border-left:1px solid var(--dtr-line2, #cde6dd);border-right:1px solid var(--dtr-line2, #cde6dd);width:24px}",

            "#dia-ps-board *::-webkit-scrollbar,#dia-ps-board-add *::-webkit-scrollbar{width:9px;height:9px}",
