            "#dia-ps-board li.object .cv2-clip-add{display:none;position:absolute;bottom:4px;left:50%;transform:translateX(-50%);width:26px;height:26px;border-radius:50%;background:var(--dtr-act1,#5fb3e8);color:var(--dtr-onfill,#fff);border:2px solid var(--dtr-card, #fff);align-items:center;justify-content:center;cursor:pointer;padding:0!important;box-shadow:0 2px 6px var(--dtr-shade2, rgba(0,0,0,.2));transition:all .15s;z-index:10}",
