            "#dia-ps-board .dia-psb-clip{flex:0 1 auto;border-top:1px solid var(--dtr-cream, #f0ebe0);background:var(--dtr-card, #fff);max-height:56vh;display:flex;flex-direction:column;min-height:0}",
