            "#dia-ps-board .dia-psb-clip-tiles{display:flex;flex-wrap:wrap;gap:10px;justify-content:center;padding:2px 0 6px}",
            "#dia-ps-board .dia-psb-clip-item{cursor:grab;position:relative;flex:none;width:208px;background:var(--dtr-card,#fff);color:var(--dtr-ink,#4a4453);border:1px solid var(--dtr-lilac,#ded0e4);border-radius:12px;padding:4px 8px 4px 4px;display:flex;flex-direction:row;gap:8px;text-align:left;align-items:center;gap:2px;transition:border-color .12s,box-shadow .12s}",
