            "#dia-ps-board-add .dia-psa-rnm{font:700 12px Nunito,Arial,sans-serif;color:var(--dtr-ink-strong, #3a3a35);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}",
            "#dia-ps-board-add .dia-psa-rsp{font:600 10px Nunito,Arial,sans-serif;color:var(--dtr-grey5, #9a9a90)}",
            "#dia-ps-board-add .dia-psa-rother{flex:none;font:700 9px Nunito,Arial,sans-serif;color:#b58a6a;background:var(--dtr-cream, #f3ece2);border-radius:999px;padding:2px 8px}",
            "#dia-ps-board-add .dia-psa-radd{flex:none;font:800 12px Nunito,Arial,sans-serif;color:var(--dtr-primary,#149c8e);min-width:54px;text-align:right}",
