  function _dtrEdgeTabHTML(label, count) {
    return _DTR_ET_IC_SVG + '<span class="dtr-et-label">' + label + '</span>'
      + (count ? '<span class="dtr-et-count">' + count + '</span>' : '');
  }
  function _dtrMkEdgeTab(id, label, count, title) {
    _dtrEdgeTabCss();
    const tab = document.createElement('button');
    tab.id = id; tab.type = 'button'; tab.className = 'dtr-edgetab';
    if (title) tab.title = title;
    tab.innerHTML = _dtrEdgeTabHTML(label, count);
    return tab;
  }

  function _dtrEdgeTabStall(tab, msg) {
    try {
      if (!tab || !document.body) return;
      tab.classList.remove('opening');
      if (!document.body.contains(tab)) document.body.appendChild(tab);
      const id = tab.id + '-stall';
      if (document.getElementById(id)) return;
      const note = document.createElement('div');
      note.id = id; note.className = 'dtr-et-stall'; note.setAttribute('role', 'status');
      note.textContent = msg;
      document.body.appendChild(note);
      setTimeout(() => { try { note.remove(); } catch (_) {} }, 9000);
    } catch (_) {}
  }

  function _dtrOpenTabRetry(tab, panelId, build, stallMsg) {
    const done = () => !!document.getElementById(panelId);
    if (tab.classList.contains('opening')) return;
    try { document.getElementById(tab.id + '-stall').remove(); } catch (_) {}
    try { build(); } catch (_) {}
    if (done()) return;
    tab.classList.add('opening');
    let m = 0;
    const iv = setInterval(() => {
      try { build(); } catch (_) {}
      if (done()) { clearInterval(iv); tab.classList.remove('opening'); return; }
      if (++m > 30) {
        clearInterval(iv);
        let msg = stallMsg;
        if (typeof msg === 'function') { try { msg = msg(); } catch (_) { msg = ''; } }
        _dtrEdgeTabStall(tab, msg);
      }
    }, 400);
  }

