  var _dtrGalleryBgPending = false;
  function _dtrGalleryQueueHandoff() {
    if (location.hostname !== 'impress.openneo.net') return;
    if (!window.dtrRoute.is('items') || !/[?&]dti_sync=bulk(?:&|$)/.test(location.search)) return;
    if (_dtrImportSrc() !== 'gallery') return;
    let q = null;
    try { q = JSON.parse(window.dtrStore.get(DTR_GALLERY_QUEUE_KEY, '') || 'null'); } catch (_) {}
    if (!q || !Array.isArray(q.items) || !q.items.length) return;
    if (Date.now() - (q.ts || 0) > 5 * 60 * 1000) { try { window.dtrStore.del(DTR_GALLERY_QUEUE_KEY); } catch (_) {} return; }
    try { window.dtrStore.del(DTR_GALLERY_QUEUE_KEY); } catch (_) {}
    const buildBatch = (keep) => {
      const batch = loadBatch('gallery') || {};
      const added = {};
      const done = _dibDoneMap('gallery');
      keep.forEach(it => {
        const nm = _dibNormName((it && it.name) || ''); if (!nm) return;
        const want = Math.max(0, (parseInt(it.qty, 10) || 1) - (parseInt(done[nm], 10) || 0));
        if (!want) return;
        const have = parseInt(batch[nm], 10) || 0;
        const next = Math.max(have, want);
        if (next > have) { batch[nm] = next; added[nm] = next - have; }
      });
      if (Object.keys(added).length) {
        saveBatch(batch, 'gallery');
        try { recordImport(added, 'gallery'); } catch (_) {}
        try { window.dtrStore.set(BATCH_TS_KEY + _dtrSrcSuffix('gallery'), Date.now()); } catch (_) {}
        diaTouchImport('gallery');
      }
    };
    const rebuild = () => {
      if (!(window.dtrRoute.is('items') && /[?&]dti_sync=bulk(?:&|$)/.test(location.search) && _dtrImportSrc() === 'gallery')) return;
      const r = document.getElementById('dia-bulk-root'); if (r) { try { r.remove(); } catch (_) {} try { diaInitBulkSync(); } catch (_) {} }
    };
    if (!q.ncOnly) {
      buildBatch(q.items);
      if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => setTimeout(rebuild, 60)); else setTimeout(rebuild, 60);
      return;
    }

    _dtrGalleryBgPending = true;
    const run = async () => {
      try {
        const names = q.items.map(i => i.name);
        const resolved = await diaBulkResolveItems(names, (d, t) => {
          const e = document.querySelector('#dia-bulk-wrap .dib-empty'); if (e) e.textContent = 'Finding your NC items… ' + d + '/' + t;
        });
        buildBatch(q.items.filter(it => { const r = resolved[it.name]; return r && r.nc; }));
      } catch (_) {}
      _dtrGalleryBgPending = false;
      rebuild();
    };
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => setTimeout(run, 80)); else setTimeout(run, 80);
  }

  function diaBulkListKey(side, name) {
    return `${side}:${String(name || '').toLowerCase().trim()}`;
  }

  function diaBulkUserSlug() {
    const m = document.querySelector('a[href*="/user/"]')?.href?.match(/\/user\/(\d+)-([^\/]+)/);
    return m ? (m[1] + '-' + m[2]) : null;
  }

  const dibEsc = (x) => String(x == null ? '' : x).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

  function dibStepperHtml(o, extraClass) {
    return `
          <div class="dib-numtile${extraClass ? ' ' + extraClass : ''}">
            <input class="dib-num${o.numClass || ''}" type="text" inputmode="numeric" value="${o.q}" aria-label="Quantity, type a number, or use minus and plus" />
            <div class="dib-side l${o.disableDec ? ' disabled' : ''}" data-act="dec" aria-label="decrease"><span class="dib-g">−</span></div>
            <div class="dib-side r" data-act="inc" aria-label="increase"><span class="dib-g">+</span></div>
          </div>`;
  }
  function dibOwnedCellHtml(o) {
    const vis = o.vis ? `<span class="dib-vis ${String(o.vis).toLowerCase()}">${dibEsc(o.vis)}</span>` : '';
    return `
        <div class="dib-cell dib-tile ${o.q > 0 ? 'has' : ''}${o.cellClass || ''}" draggable="true" ${o.attrs || ''}>
          <div class="dib-chead">
            <span class="dib-grip dib-cgrip" aria-hidden="true" title="Drag to reorder">⠿</span>
            ${o.pens != null ? o.pens : '<button class="dib-pen" type="button" data-act="listmenu" aria-label="Manage list">' + window.dtrIcon.html('edit', { size: 11 }) + '</button>'}
            <div class="dib-visrow">${vis}</div>
            <div class="dib-nmwrap"><div class="dib-nm" style="font-size:${o.fs}px" title="${dibEsc(o.title != null ? o.title : o.name)}">${dibEsc(o.name)}</div></div>
          </div>
          ${dibStepperHtml(o)}
        </div>`;
  }
  function dibWantRowHtml(o) {
    const vis = o.vis ? `<span class="dib-vis ${String(o.vis).toLowerCase()}">${dibEsc(o.vis)}</span>` : '';
    return `
        <div class="dib-wrow${o.q > 0 ? ' has' : ''}${o.cellClass || ''}" draggable="true" ${o.attrs || ''}>
          <span class="dib-grip dib-wgrip" aria-hidden="true" title="Drag to reorder">⠿</span>
          <span class="dib-wrow-nmwrap">${vis}<span class="dib-wrow-nm" title="${dibEsc(o.title != null ? o.title : o.name)}">${dibEsc(o.name)}${o.tag || ''}</span></span>
          ${dibStepperHtml(o, 'dib-wnumtile')}
          ${o.pens != null ? o.pens : '<button class="dib-wpen" type="button" data-act="listmenu" aria-label="Manage list">' + window.dtrIcon.html('edit', { size: 13 }) + '</button>'}
        </div>`;
  }

  const DTR_HANGER_SVG = '<svg class="dtr-hanger" viewBox="0 0 24 24" width="13" height="13" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M10.3 5.2a2.2 2.2 0 1 1 3 2.05c-.8.34-1.3.85-1.3 1.55v.5"/><path d="M12 9.3 4.5 14.2a1.75 1.75 0 0 0 .96 3.2h13.08a1.75 1.75 0 0 0 .96-3.2L12 9.3Z"/></svg>';

  const DTR_ITEM_HANGER_SVG = DTR_HANGER_SVG;

  try { window.__DTR_ICONS = { hanger: DTR_HANGER_SVG, itemHanger: DTR_ITEM_HANGER_SVG, note: DIA_ICON_NOTE }; } catch (_) {}

  function diaBulkAllLists(listMeta) {
    const hidden = readJSON(HIDDEN_KEY, {});
    const nicknames = readJSON(NICKNAME_KEY, {});
    const order = readJSON(ORDER_KEY, {});

    const all = Object.entries(listMeta).map(([listId, m]) => {
      const side = m.wanted ? 'want' : 'own';
      const key = diaBulkListKey(side, m.name);
      return {
        listId, side, key,
        name: m.name,
        display: nicknames[key] || m.name,
        visibility: m.visibility || '',
        hidden: !!hidden[key],
      };
    });

    const sortSide = (arr, side) => {
      const ord = order[side] || [];
      return arr.sort((a, b) => {
        const ia = ord.indexOf(a.key), ib = ord.indexOf(b.key);
        if (ia === -1 && ib === -1) return 0;
        if (ia === -1) return 1;
        if (ib === -1) return -1;
        return ia - ib;
      });
    };

    return {
      own: sortSide(all.filter(l => l.side === 'own'), 'own'),
      want: sortSide(all.filter(l => l.side === 'want'), 'want'),
    };
  }

  function diaBulkVisibleLists(listMeta) {
    const showAll = !!window.dtrStore.get(SHOW_HIDDEN_KEY, false);
    const all = diaBulkAllLists(listMeta);
    return {
      own: all.own.filter(l => showAll || !l.hidden),
      want: all.want.filter(l => showAll || !l.hidden),
    };
  }

  async function diaBulkLoadCloset(slug) {
    const out = { listMeta: {}, itemQty: {}, csrf: null, allListIds: [] };
    if (!slug) return out;
    const resp = await fetch('/user/' + slug + '/closet', { credentials: 'include' });
    if (!resp.ok) return out;
    const doc = new DOMParser().parseFromString(await resp.text(), 'text/html');

    out.csrf = window.dtrDom.csrfToken(doc) || null;

    const wantedIds = new Set(
      [...doc.querySelectorAll('#closet-hangers-group-false [id^="closet-list-"]')]
        .map(l => l.id.replace('closet-list-', ''))
    );

    out.allListIds = [...doc.querySelectorAll('[id^="closet-list-"]')].map(l => {
      const listId = l.id.replace('closet-list-', '');
      const name = l.querySelector('.closet-list-name, h3, h4')?.textContent?.trim() || listId;
      const visSel = l.querySelector('select[name*="visibility"]');
      const visibility = visSel ? (visSel.options[visSel.selectedIndex]?.text?.trim() || '') : '';
      out.listMeta[listId] = { name, wanted: wantedIds.has(listId), visibility };
      return listId;
    });

    doc.querySelectorAll('#closet-hangers [data-item-id]').forEach(el => {
      const itemId = el.dataset.itemId;
      const qty = parseInt(el.dataset.quantity) || 1;
      const listId = el.closest('[id^="closet-list-"]')?.id?.replace('closet-list-', '');
      if (itemId && listId) {
        (out.itemQty[itemId] = out.itemQty[itemId] || {})[listId] = qty;
      }
    });

    return out;
  }

  const DTR_RESOLVE_CACHE_KEY = 'dtr_item_resolve_cache';
  async function diaBulkResolveItems(names, onProgress) {
    const result = {};
    const norm = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();

    let cache = {};
    try { cache = JSON.parse(GM_getValue(DTR_RESOLVE_CACHE_KEY, '') || '{}') || {}; } catch (_) { cache = {}; }
    const toFetch = [];
    names.forEach(name => {
      const c = cache[norm(name)];

      if (c && c.id && 'nc' in c) result[name] = { id: String(c.id), slug: c.slug || '', thumb: c.thumb || '', nc: !!c.nc, pb: ('pb' in c ? !!c.pb : undefined) };
      else toFetch.push(name);
    });
    const total = toFetch.length;
    if (!total) return result;

    let done = 0, dirty = false;
    const queue = [...toFetch];

    const _sleep = ms => new Promise(r => setTimeout(r, ms));
    const worker = async () => {
      while (queue.length) {
        const name = queue.shift();

        const cleanName = _dtrDecodeEntities(name);
        try {

          const _squash = s => norm(_dtrDecodeEntities(s)).replace(/[^a-z0-9]/g, '');
          const _tokens = s => new Set(norm(_dtrDecodeEntities(s)).replace(/[^a-z0-9 ]+/g, ' ').split(/\s+/).filter(Boolean));
          const _tryQuery = async (q, allowSole) => {
            const resp = await fetch('/items.json?q=' + encodeURIComponent(q));
            if (!resp.ok) return null;
            const data = await resp.json();
            const items = Array.isArray(data) ? data : (data.items || []);
            let h = items.find(i => norm(i.name) === norm(cleanName)) || (allowSole && items.length === 1 ? items[0] : null);
            if (!h) {
              const sq = _squash(cleanName);
              const sqHits = items.filter(i => _squash(i.name) === sq);
              if (sqHits.length === 1) h = sqHits[0];
            }

            if (!h) {
              const dw = norm(cleanName).match(/^dyeworks ([a-z]+)\b/);
              if (dw) {
                const wTok = _tokens(cleanName);
                const cands = items.filter(i => {
                  const m2 = norm(i.name).match(/^dyeworks ([a-z]+)\b/);
                  if (!m2 || m2[1] !== dw[1]) return false;
                  const cTok = _tokens(i.name);
                  return [...cTok].every(t => wTok.has(t)) || [...wTok].every(t => cTok.has(t));
                });
                if (cands.length === 1) h = cands[0];
              }
            }
            return h || null;
          };
          {
            let hit = await _tryQuery(cleanName, true);

            if (!hit) {
              const plain = cleanName.replace(/[^a-zA-Z0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
              if (plain && norm(plain) !== norm(cleanName)) { try { hit = await _tryQuery(plain, false); } catch (_) {} }
            }

            if (!hit) {
              const mdw = cleanName.match(/^Dyeworks\s+([A-Za-z]+)/i);
              if (mdw) {
                const ws = cleanName.replace(/[^a-zA-Z0-9]+/g, ' ').trim().split(' ');
                try { hit = await _tryQuery('Dyeworks ' + mdw[1] + ' ' + ws.slice(-2).join(' '), false); } catch (_) {}
              }
            }
            if (!hit && cleanName.indexOf(' ') > -1) {
              const words = cleanName.split(' ').filter(Boolean);
              for (let w = 0; !hit && w < words.length - 1 && w < 4; w++) {
                const variant = words.slice(0, w).concat(words[w] + words[w + 1]).concat(words.slice(w + 2)).join(' ');
                try { hit = await _tryQuery(variant, false); } catch (_) {}
              }
            }
            if (hit && norm(hit.name) !== norm(cleanName)) { try {  } catch (_) {} }
            if (hit) {
              const rec = {
                id: String(hit.id),
                slug: hit.name ? norm(hit.name).replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') : '',
                thumb: hit.thumbnail_url || hit.thumbnail || '',
                nc: !!hit['nc?'],
                pb: !!hit['pb?'],
              };
              result[name] = rec;
              cache[norm(name)] = rec; dirty = true;
            }
          }
        } catch (_) {  }
        done++;
        onProgress && onProgress(done, total);
        if (queue.length) await _sleep(8);
      }
    };

    await Promise.all(Array.from({ length: Math.min(8, total) }, worker));
    if (dirty) { try { GM_setValue(DTR_RESOLVE_CACHE_KEY, JSON.stringify(cache)); } catch (_) {} }
    return result;
  }

  function diaBulkResolveCached(names) {
    const norm = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
    let cache = {};
    try { cache = JSON.parse(GM_getValue(DTR_RESOLVE_CACHE_KEY, '') || '{}') || {}; } catch (_) { cache = {}; }
    const out = {};
    (names || []).forEach(n => { const c = cache[norm(n)]; if (c && c.id) out[n] = { id: String(c.id), slug: c.slug || '', thumb: c.thumb || '', nc: ('nc' in c ? !!c.nc : undefined), pb: ('pb' in c ? !!c.pb : undefined) }; });
    return out;
  }

  async function diaBulkSaveItem(slug, item, allListIds, csrf) {
    const formAction = '/user/' + slug + '/items/' + item.id + '-' + item.slug + '/closet_hangers/update_quantities';
    const body = new URLSearchParams();
    body.set('_method', 'put');
    body.set('authenticity_token', csrf);

    const _known = new Set([...Object.keys(item.current || {}), ...Object.keys(item.alloc || {})]);
    _known.forEach(listId => {
      if (listId === 'true' || listId === 'false') return;
      body.set('quantity[' + listId + ']', String(item.alloc[listId] || 0));
    });
    let lastErr;
    for (let attempt = 0; attempt < 3; attempt++) {
      try {
        const resp = await fetch(formAction, {
          method: 'POST',
          credentials: 'include',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded', 'X-CSRF-Token': csrf },
          body: body.toString(),
        });

        if (/\/(users\/)?sign_in|\/login|\/account\/login/i.test(resp.url || '')) throw new Error('not signed in');
        if (!resp.ok) throw new Error('save failed ' + resp.status);

        try {  } catch (_) {}
        return;
      } catch (e) {
        lastErr = e;
        try {  } catch (_) {}
        if (attempt < 2) await new Promise(r => setTimeout(r, 450 * (attempt + 1)));
      }
    }
    throw lastErr || new Error('save failed');
  }

  function diaBulkEsc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, c => (
      { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]
    ));
  }

  function diaScrapeNavInfo() {
    const dtiNav = document.querySelector('nav, header, #main-nav, #header');
    const navText = dtiNav?.textContent || document.body?.textContent || '';
    const heyMatch = navText.match(/Hey,\s*([^!\s]+)!/);
    const ptsMatch = navText.match(/([\d,]+)\s+points/i);
    let _pts = ptsMatch?.[1] || '';
    try { if (_pts) GM_setValue('dtr_last_pts', _pts); else _pts = GM_getValue('dtr_last_pts', '') || ''; } catch (e) {}
    const greeting = heyMatch?.[1] || '';
    try { if (greeting) GM_setValue('dtr_last_user', greeting); } catch (_) {}
    return {
      greeting,
      pts: _pts,
      logoutHref: window.dtrDom.logoutHref(),
      itemsHref: document.querySelector('a[href*="/user/"][href*="/closet"]')?.href || '/users/current-user/closet',
    };
  }

  function _dtrNstText() {
    try {
      return new Date().toLocaleTimeString('en-US', {
        timeZone: 'America/Los_Angeles', hour: 'numeric', minute: '2-digit', second: '2-digit', hour12: true,
      }).toLowerCase().replace(/s+/g, ' ');
    } catch (_) { return ''; }
  }
  function _dtrNstTick() {
    try {
      var t = _dtrNstText();
      var els = document.querySelectorAll('[data-nst]');
      for (var i = 0; i < els.length; i++) if (els[i].textContent !== t) els[i].textContent = t;
    } catch (_) {}
    try { _dtrWatchNavFit(); } catch (_) {}
  }

  var _NAV_FIT_STEPS = ['dia-nav-tight', 'dia-nav-noclock', 'dia-nav-tighter', 'dia-nav-nogreet', 'dia-nav-nodivs'];

  var _navMenuOpen = function (nav) { return !!nav.querySelector('.dia-gearwrap.open, .dia-more.open'); };
  window._dtrFitNav = function () {
    var nav = document.getElementById('dia-hp-nav');
    if (!nav || !nav.isConnected || !nav.offsetWidth) return;
    if (_navMenuOpen(nav)) return;
    _NAV_FIT_STEPS.forEach(function (c) { nav.classList.remove(c); });
    for (var i = 0; i < _NAV_FIT_STEPS.length; i++) {

      if (nav.scrollWidth - nav.clientWidth <= 1) return;
      nav.classList.add(_NAV_FIT_STEPS[i]);
    }
  };

  function _dtrWatchNavFit() {
    var nav = document.getElementById('dia-hp-nav');
    if (!nav || !nav.offsetWidth) return;
    var p = nav.parentElement; if (!p) return;
    if (_navMenuOpen(nav)) return;
    var avail = p.clientWidth;
    if (nav.__dtrFitAvail !== avail || nav.scrollWidth - nav.clientWidth > 1) {
      nav.__dtrFitAvail = avail;
      window._dtrFitNav();
    }
  }
  if (IS_IMPRESS) try { window.addEventListener('resize', function () { try { window._dtrFitNav(); } catch (_) {} }); } catch (_) {}

  if (IS_IMPRESS) try {
    var _navFitBurst = 0;
    var _navFitTimer = setInterval(function () {
      if (++_navFitBurst > 60) { clearInterval(_navFitTimer); return; }
      try { _dtrWatchNavFit(); } catch (_) {}
    }, 300);
    document.addEventListener('turbo:load', function () { try { _dtrWatchNavFit(); } catch (_) {} });
  } catch (_) {}
  try {
    if (IS_IMPRESS && !window.__dtrNstTimer) {
      _dtrNstTick();
      window.__dtrNstTimer = setInterval(_dtrNstTick, 1000);
      document.addEventListener('turbo:load', _dtrNstTick);

      document.addEventListener('visibilitychange', function () { if (!document.hidden) _dtrNstTick(); });
    }
  } catch (_) {}

