        'body.outfits-index #dtr-yo-root .dtr-yo-menurow:hover,body.outfits-index #dtr-yo-root .dtr-yo-menurow:focus{background:var(--dtr-cream, #f6f3ec)!important;color:var(--dtr-ink,#564f60)!important;}',
        '.dtr-yo-menurow.on{background:var(--dtr-cream, #f4f1e8);color:var(--dtr-ink-strong, #3a3a35);font-weight:800}',

        '.dtr-yo-toggle{padding:0 12px;height:44px;box-sizing:border-box;border-radius:12px;cursor:pointer;font:700 12px "Nunito",sans-serif;background:var(--dtr-card, #fff);border:1.5px solid var(--border,#e7e1d4);color:var(--dtr-grey7, #5b5b54);display:inline-flex;align-items:center;gap:5px}',
        '.dtr-yo-toggle.on{background:var(--dtr-primary,#149c8e);border-color:var(--dtr-primary,#149c8e);color:var(--dtr-onfill,#fff)}',

        '.dtr-yo-views{display:flex;align-items:center;background:var(--dtr-cream, #f4f1e8);border:1px solid var(--border,#e7e1d4);border-radius:12px;padding:2px;height:44px;box-sizing:border-box}',
        '.dtr-yo-view{width:30px;height:100%;border-radius:10px;border:none;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;background:transparent;color:var(--dtr-grey5, #9a9a90);padding:0}',
        '.dtr-yo-view.on{background:var(--dtr-primary,#149c8e);color:var(--dtr-onfill,#fff)}',

