        '#dtr-yo-grid.strip{display:flex;flex-direction:column;flex-wrap:nowrap;justify-content:flex-start;align-items:stretch}',

        '#dtr-yo-root{--border:var(--dtr-line,#e7e1d4)}',
        '.dtr-yo-card{position:relative;background:var(--dtr-card, #fff);border:1px solid var(--border,#e7e1d4);border-radius:16px;box-shadow:0 4px 10px -5px var(--dtr-hairline, rgba(60,60,55,.07));overflow:visible;display:flex;flex-direction:column;transition:box-shadow .12s}',
