        '.dtr-yo-vthumb>.dtr-yo-vsel{position:absolute;top:3px;left:3px;right:3px;width:auto;height:auto;z-index:3;border-radius:11px 11px 0 0;background:linear-gradient(var(--dtr-glass, rgba(255,251,245,.86)),var(--dtr-glass, rgba(255,251,245,.86))),var(--dtr-stripe,linear-gradient(90deg,#1cb6a6 0 25%,#5fb3e8 25% 45%,#ff97b3 45% 72%,#ffce5a 72% 100%));background-origin:border-box;background-clip:border-box;color:var(--dtr-ink-strong, #4a4a45);text-align:center;font:800 6.5px/1.35 "Nunito",sans-serif;letter-spacing:.06em;text-transform:uppercase;padding:2.5px 2px;pointer-events:none;box-shadow:none}',
        '.dtr-yo-vthumb.hid>span{opacity:.45}',

        '.dtr-yo-vthumb>.dtr-yo-vnum{position:absolute;top:-4px;left:-4px;z-index:4;min-width:20px;width:auto;height:20px;padding:0 5px;box-sizing:border-box;border-radius:999px;background:rgba(40,36,30,.66);color:#fff;display:flex;align-items:center;justify-content:center;font:800 11px/1 "Nunito",sans-serif;box-shadow:0 1px 4px var(--dtr-scrim, rgba(0,0,0,.28))}',

        '.dtr-yo-vthumb>.dtr-yo-vcrown{position:absolute;top:-19px;left:50%;z-index:5;width:30px;height:26px;padding:0;background:transparent;border:none;display:flex;align-items:center;justify-content:center;cursor:pointer;opacity:0;pointer-events:none;transform:translateX(-50%) scale(.9);transform-origin:bottom center;transition:opacity .12s,transform .12s}',
