  function isActiveDTISyncTab() {
    if (location.hostname !== 'impress.openneo.net') return false;

    const pending = loadPendingSync();

    if (!pending || !pending.names || !pending.names.length) return false;

    const q = new URLSearchParams(location.search).get('q') || '';

    if (!q) return !!pending;

    return pending.names.some(name => normalize(q) === normalize(name));
  }

  function detectDTILoginStateFromPage() {
    if (location.hostname !== 'impress.openneo.net') return null;

    const linksAndButtons = [...document.querySelectorAll('a, button, input[type="submit"]')];

    const hasLogoutControl = linksAndButtons.some(el => {
      const text = (el.textContent || el.value || '').replace(/\s+/g, ' ').trim();
      const href = el.getAttribute?.('href') || '';
      const action = el.closest?.('form')?.getAttribute?.('action') || '';

      return (
        /\b(log out|logout|sign out|signout)\b/i.test(text) ||
        /sign_out|logout|log_out/i.test(href) ||
        /sign_out|logout|log_out/i.test(action)
      );
    });

    if (hasLogoutControl) return 'logged_in';

    const hasLoginControl = linksAndButtons.some(el => {
      const text = (el.textContent || el.value || '').replace(/\s+/g, ' ').trim();
      const href = el.getAttribute?.('href') || '';
      const id = el.getAttribute?.('id') || '';
      const className = el.getAttribute?.('class') || '';

      return (
        /\b(log in|login|sign in|signin)\b/i.test(text) ||
        /sign_in|login|log_in/i.test(href) ||
        /sign[_-]?in|log[_-]?in/i.test(id) ||
        /sign[_-]?in|log[_-]?in/i.test(className)
      );
    });

    if (hasLoginControl) return 'logged_out';

    return 'unknown';
  }

  function updateDTILoginStateFromPage() {
    const state = detectDTILoginStateFromPage();

    if (state) {
      setStoredDTILoginState(state);
    }

    return state;
  }

  function dtiPageHasVisibleLoginControl() {
    if (location.hostname !== 'impress.openneo.net') return false;

    return [...document.querySelectorAll('a, button, input[type="submit"]')].some(el => {
      const label = (el.textContent || el.value || '').replace(/\s+/g, ' ').trim();
      const href = el.getAttribute?.('href') || '';
      const rect = el.getBoundingClientRect?.();
      const style = window.getComputedStyle ? window.getComputedStyle(el) : null;

      const looksLikeLogin =
        /^log in$/i.test(label) ||
        /^login$/i.test(label) ||
        /^sign in$/i.test(label) ||
        /\/login|sign_in|log_in/i.test(href);

      const visible =
        !rect ||
        (
          rect.width > 0 &&
          rect.height > 0 &&
          (!style || (style.display !== 'none' && style.visibility !== 'hidden'))
        );

      return looksLikeLogin && visible;
    });
  }

  function showLoginBannerIfNeeded() {
    if (location.hostname !== 'impress.openneo.net') return;
    if (!isActiveDTISyncTab()) return;

    const check = () => {
      if (!isActiveDTISyncTab()) return;

      const state = updateDTILoginStateFromPage();

      if (state === 'logged_out' || dtiPageHasVisibleLoginControl()) {
        setStoredDTILoginState('logged_out');
        showDTILoginFailedBanner();
        lockDTISyncUI();
      }
    };

    check();
    setTimeout(check, 250);
    setTimeout(check, 800);
    setTimeout(check, 1600);
    setTimeout(check, 3000);
  }

  function watchDTILoginSuccessReturnToInventory() {
    if (location.hostname !== 'impress.openneo.net') return;
    if (!isActiveDTISyncTab()) return;

    let redirected = false;

    const check = () => {
      if (redirected) return;

      const pageText = document.body ? document.body.textContent || '' : '';

      if (/signed in successfully/i.test(pageText)) {
        redirected = true;
        setStoredDTILoginState('logged_in');
        clearPendingSync();

        window.location.href = 'https://www.neopets.com/inventory.phtml';
      }
    };

    check();

    if (document.body) {
      const observer = new MutationObserver(check);

      observer.observe(document.body, {
        childList: true,
        subtree: true,
        characterData: true
      });

      setTimeout(() => observer.disconnect(), 10000);
    }

    setTimeout(check, 400);
    setTimeout(check, 1200);
    setTimeout(check, 2500);
  }

  function lockDTISyncUI() {
    if (!isActiveDTISyncTab()) return;

    const existing = document.querySelector('.neo-dti-sync-lock');
    if (existing) return;

    const target =
      document.querySelector('#dia-main-row') ||
      document.querySelector('#dia-work-grid') ||
      document.querySelector('#content') ||
      document.body;

    if (!target) return;

    if (window.getComputedStyle(target).position == 'static') {
      target.style.position = 'relative';
    }

    const overlay = document.createElement('div');
    overlay.className = 'neo-dti-sync-lock';

    overlay.innerHTML = `
      <div class="neo-dti-sync-lock-card">
        <strong>DTI Sync Locked</strong>
        Finish logging into DTI before using the enhanced sync view.
      </div>
    `;

    target.appendChild(overlay);
  }

  function showDTILoginFailedBanner() {
    if (location.hostname !== 'impress.openneo.net') return;
    if (document.getElementById('neo-dti-login-failed-banner')) return;

    const attachBanner = () => {
      if (!document.body || document.getElementById('neo-dti-login-failed-banner')) return;

      const style = document.createElement('style');
      style.id = 'neo-dti-login-failed-style';
      style.textContent = `
        #neo-dti-login-failed-banner {
          position: fixed;
          top: 18px;
          left: 50%;
          transform: translateX(-50%);
          z-index: 2147483647;
          width: min(680px, calc(100vw - 32px));
          box-sizing: border-box;
          padding: 18px 20px;
          border: 2px solid #de7d1f;
          border-radius: 16px;
          background: var(--dtr-card, #fff8ee);
          color: var(--dtr-ink-max, #1a2e28);
          font-family: Arial, Helvetica, sans-serif;
          box-shadow: 0 12px 34px var(--dtr-shade2, rgba(0,0,0,0.24));
          line-height: 1.35;
        }

        #neo-dti-login-failed-banner .neo-dti-login-failed-close {
          position: absolute;
          top: 8px;
          right: 10px;
          border: none;
          background: transparent;
          color: #8a5a25;
          font: 900 18px Arial, Helvetica, sans-serif;
          line-height: 1;
          cursor: pointer;
          padding: 3px 6px;
        }

        #neo-dti-login-failed-banner .neo-dti-login-failed-close:hover {
          color: var(--dtr-deep, #1a4a38);
        }

        #neo-dti-login-failed-banner strong {
          display: block;
          margin-bottom: 6px;
          color: var(--dtr-deep, #1a4a38);
          font-size: 18px;
          font-weight: 900;
          padding-right: 28px;
        }

        #neo-dti-login-failed-banner p {
          margin: 0 0 10px;
          font-size: 14px;
        }

        #neo-dti-login-failed-banner .neo-dti-login-inline {
          display: inline;
          margin: 0;
          padding: 0;
          color: var(--dtr-deep, #1a4a38);
          font-size: 14px;
          font-weight: 900;
        }
      `;

      document.head.appendChild(style);

      const banner = document.createElement('div');
      banner.id = 'neo-dti-login-failed-banner';
      banner.innerHTML = `
        <button class="neo-dti-login-failed-close dtr-x" type="button" aria-label="Dismiss">${window.dtrIcon.html('close', { size: 14 })}</button>
        <strong>DTI sync from inventory failed</strong>
        <p>You are not logged into Dress to Impress, so the inventory sync could not start.</p>
        <p><strong class="neo-dti-login-inline">Log in.</strong> After logging in, head back to inventory to retry syncing.</p>
      `;

      document.body.appendChild(banner);

      const closeBtn = banner.querySelector('.neo-dti-login-failed-close');
      if (closeBtn) {
        closeBtn.addEventListener('click', () => {
          banner.remove();
        });
      }
    };

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', attachBanner, { once: true });
    } else {
      attachBanner();
    }
  }

