          const els = ['dia-hp-tryon-panel', 'dia-hp-wl-panel', 'dtr-tophat', 'dia-tryon-picker-drawer']
            .map(id => document.getElementById(id))
            .filter(el => el && el.style.display !== 'none');
          if (!els.length) return;
          const sx = e.clientX, sy = e.clientY;
          const getTx = (el) => { const m = (el.style.transform || '').match(/translate\((-?[\d.]+)px,\s*(-?[\d.]+)px\)/); return m ? { x: parseFloat(m[1]), y: parseFloat(m[2]) } : { x: 0, y: 0 }; };
          const start = els.map(getTx);
          handle.style.cursor = 'grabbing';
          e.preventDefault();
          const onMove = (mv) => { const dx = mv.clientX - sx, dy = mv.clientY - sy; els.forEach((el, i) => { el.style.transform = `translate(${start[i].x + dx}px, ${start[i].y + dy}px)`; }); };
          const onUp = () => { handle.style.cursor = 'grab'; document.removeEventListener('mousemove', onMove); document.removeEventListener('mouseup', onUp); };
