        mine: !!(id && _oeIsMine(id)),
        locked: !!oeActiveVar(st).locked,
        sig: id ? _oeActiveSig(st) : null,
        savedSig: key ? _oeSavedSigById[key] : undefined,
        worn: _oeWornIds(st.considering).length,
