          activeIdx: to, variants: v,
          considering: ((tv.items) || []).slice(),
          outfitId: tv.outfitId || null, outfitName: tv.name || s2.outfitName,
          speciesId:   pick('speciesId', s2.speciesId),
          colorId:     pick('colorId', s2.colorId),
