    function oeLoadPacks() {
      try { const r = JSON.parse(window.dtrStore.get('dtr:oe:starter_packs', '') || '[]'); if (Array.isArray(r) && r.length) return r; } catch (_) {}
      return [{ name: 'My Starter Pack', items: [] }];
    }
    function oeSavePacks(packs) { try { window.dtrStore.set('dtr:oe:starter_packs', JSON.stringify(packs || [])); } catch (_) {} }

    async function oeQuickstartPack() {
      try {
        if (!window.dtrRoute.is('editor-new')) return;

        if ((new URLSearchParams(location.search).get('name') || '').trim()) return;

        let nm = new URLSearchParams(location.search).get('dtr_pack');
        if (!nm) { try { nm = String(window.dtrStore.get('dtr:settings:quickstart_pack', '') || ''); } catch (_) {} }
        if (!nm) return;
        const st0 = OE.get();

        if ((st0.considering || []).length) return;
        const pk = (st0.packs || []).find(p => p && (p.name || '') === nm);
        if (!pk || !(pk.items || []).filter(x => x && x.id).length) {  return; }
        const pitems = pk.items.filter(x => x && x.id);
        const checked = await Promise.all(pitems.map(async it => {
          try {
            const la = await oeFetchItemLayersOE(String(it.id), OE.get().speciesId, OE.get().colorId);
            return { it, fits: ((la && la.layers) || []).length > 0 };
          } catch (_) { return { it, fits: true }; }
        }));

        const add = checked.map(({ it, fits }) => ({
          name: it.name, id: String(it.id), zone: null, hue: 0, loved: false,
          applied: !!fits, bodyConflict: !fits,
          thumb: it.thumb || '', nc: !!it.nc, owned: false, pack: pk.name }));
        if (add.length) OE.set(s2 => ({ considering: [...(s2.considering || []).filter(c => !add.some(a => String(a.id) === String(c.id))), ...add] }));

      } catch (e) {  }
    }

    let _oeQsAppliedHref = '';
    let _oeSyncedSeedHref = '';
    setInterval(function () {
      try {
        if (!window.dtrRoute.is('editor-new')) { _oeQsAppliedHref = ''; return; }
        if (_oeQsAppliedHref === location.href) return;
        const _sp0 = new URLSearchParams(location.search);
        const _seedNm = (_sp0.get('name') || '').trim();
        if (_seedNm) {

          try { const _sty = _sp0.get('style'); if (_sty && window.__DTR_ABOX_LOG) window.__DTR_ABOX_LOG(_sty, _seedNm); } catch (_) {}

          if (_oeSyncedSeedHref !== location.href) { _oeSyncedSeedHref = location.href; try { oeSyncFromDTI(); } catch (_) {} }
          _oeQsAppliedHref = location.href; return;
        }

        if (_oeSyncedSeedHref !== location.href) {
          const _uSp = _sp0.get('species'), _uCo = _sp0.get('color');
          const _cur0 = OE.get();
          if (_uSp && _uCo && _cur0 && !_cur0.oeOutfitLoading
              && (String(_cur0.speciesId) !== String(_uSp) || String(_cur0.colorId) !== String(_uCo))) {
            _oeSyncedSeedHref = location.href;

            if (!_sp0.getAll('objects[]').length) {
              try { OE.set({ considering: [], watchZones: [] }); } catch (_) {}
            }
            try { oeSyncFromDTI(); } catch (_) {}
            return;
          }
        }
        let pkName = new URLSearchParams(location.search).get('dtr_pack');
        if (!pkName) { try { pkName = String(window.dtrStore.get('dtr:settings:quickstart_pack', '') || ''); } catch (_) {} }
        if (!pkName) return;
        const s = OE.get();
        if (!s || !s.speciesId || s.oeLoadingPet) return;
        if (!(s.packs || []).some(function (p) { return p && (p.name || '') === pkName; })) return;
        _oeQsAppliedHref = location.href;
        oeQuickstartPack();
      } catch (_) {}
    }, 600);

    let _packSearchDebounce = null;
    async function oeFetchPackItems(query) {
      const q = (query || '').trim();
      if (!q) return [];
      const params = new URLSearchParams(); let i = 0;
      const re = /(-?)(?:"([^"]*)"|(\S+))/g; let mm;
      while ((mm = re.exec(q)) !== null) {
        const t = (mm[2] != null ? mm[2] : (mm[3] || '')).trim();
        if (!t) continue;
        params.append('q['+i+'][key]', 'name'); params.append('q['+i+'][value]', t);
        if (mm[1] === '-') params.append('q['+i+'][is_positive]', 'false');
        i++;
      }
      if (!i) return [];
      params.append('page', '1'); params.append('per_page', '14');
      try {
        const res = await _oeFetchTimeout('/items.json?' + params.toString(), { headers: { 'Accept': 'application/json' } }, 10000);
        if (!res.ok) return [];
        const json = await res.json();
        return (json.items || []).map(it => ({ id: String(it.id), name: it.name || '', thumb: it.thumbnail_url || '', nc: !!it['nc?'] }));
      } catch (_) { return []; }
    }

