      const _capsTag = text => '<span style="' + _tagBase + ';background:radial-gradient(circle at 8px 50%,var(--dtr-card, #fff) 2.2px,var(--dtr-pink-pale, #ffe3ec) 2.9px);color:var(--dtr-berry, #c2487c)">' + _oeEsc(text) + '</span>';
