      const _wishPill = '<span style="display:inline-flex;align-items:center;padding:2px 10px;border-radius:999px;font:800 8.5px Nunito,sans-serif;letter-spacing:.04em;text-transform:uppercase;background:linear-gradient(135deg,var(--dtr-lilac, #e9e3f4),var(--dtr-lilac, #f2e2ec));color:var(--dtr-ink-plum,#8a76aa)">Wishlisted</span>';

