        for (const src of srcs) { const im = await loadImg(src); if (im) ctx.drawImage(im, 0, 0, SZ, SZ); }
        const blob = await new Promise(res => cv.toBlob(res, 'image/png'));
        if (!blob) throw new Error('toBlob');
