        catch (_) { const a = Object.assign(document.createElement('a'), { href: URL.createObjectURL(blob), download: 'variant.png' }); a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 4000); _toast('Clipboard blocked, downloaded instead'); }
