    function _oeAnchorCard(ul, scTop) {
      const ch = ul.children;
      let lo = 0, hi = ch.length - 1, ans = -1;
      while (lo <= hi) {
        const mid = (lo + hi) >> 1;
        if (ch[mid].getBoundingClientRect().bottom > scTop) { ans = mid; hi = mid - 1; }
        else lo = mid + 1;
      }
      if (ans < 0) return null;
      for (let i = ans; i < ch.length && i <= ans + 6; i++) {
        const id0 = ch[i].getAttribute && ch[i].getAttribute('data-item-id');
        if (id0 != null) { const r0 = ch[i].getBoundingClientRect(); return { id: id0, delta: r0.top - scTop }; }
      }
      return null;
    }

    let _oeKbdFocus = null, _oeKbdEnterN = 0;
