        const sel      = hasFocus ? [prevInp.selectionStart, prevInp.selectionEnd] : null;
        const prevScroll = _card && _card.querySelector('[data-results-scroll]');
        const scrollTop  = prevScroll ? prevScroll.scrollTop : 0;

