          +'<div class="dtr-card-actions"><button type=button tabindex=-1 class="dtr-note-btn'+(hasNote?' has-note':'')+'" data-note-btn="'+it.id+'" aria-label="Note">'+_OE_NOTE_IMG+'</button></div>'

