        + window.dtrIcon.html('search', { size: 14, cls: 'dtr-sf-ico' })

        +((s.searchQuery||s.activeZone) ? '<button data-search-clear title="Clear search and zone filter" style="position:absolute;right:9px;top:50%;transform:translateY(-50%);width:22px;height:22px;border-radius:50%;border:none;background:var(--dtr-cream, #e8e5dc);color:var(--dtr-grey7, #7a7a70);font-size:12px;line-height:1;cursor:pointer;display:flex;align-items:center;justify-content:center;padding:0">' + window.dtrIcon.html('close', { size: 14 }) + '</button>' : '')
        +'</div>'
        +'</div>'

        + zoneChip

        +'<div style="position:relative;display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-bottom:9px">'
