        const desired = oeSortPool(poolR, oeEffectiveSort(st));
        const existing = new Map();
        Array.prototype.forEach.call(ul.children, li => { const id = li.getAttribute && li.getAttribute('data-item-id'); if (id != null) existing.set(id, li); });
