          + _zmSurface
          + 'border-radius:'+_rad+'px;box-shadow:'+(expanded ? '0 0 0 2.5px '+S+'cc,'+OE_ZM_DEPTH : OE_ZM_DEPTH)+';cursor:'+(layoutLocked?'default':'grab')+';user-select:none;'

          + (!filled && !expanded ? '' : '');

        const searchBtnHTML = '<button data-zm-search="'+zone+'" style="display:block;width:100%;text-align:center;padding:5px 7px;border:none;border-radius:999px;background:'+S+'1e;color:var(--dtr-primary-d, #347f76);font:800 9px Nunito,sans-serif;cursor:pointer">Search</button>';
        let bodyHTML;
