    async function oeSaveOutfit() {
      const s  = OE.get();
      const av = oeActiveVar(s);

      const _mlWorn = _oeWornIds(s.considering).length;
      const _mlId   = av.outfitId || s.outfitId || null;
      const _mlAuth = _mlId != null ? _oeAuthCount[String(_mlId)] : null;

      const _mlBlock = _oeLoadingBlock({ loading: !!(_oeAutoLoading || s.oeOutfitLoading), id: _mlId,
        auth: _mlAuth, worn: _mlWorn, reachedFull: !!(_mlId != null && _oeReachedFull[String(_mlId)]) });
      if (_mlBlock) {

        throw new Error('outfit-still-loading');
      }
      const _saveIdx = s.activeIdx;

      const _mlTarget = _oeIsBorrowed(_mlId) ? null : _mlId;
      const res = await oeSaveOutfitData(av.name || s.outfitName || 'My Outfit', _oeWornIds(s.considering), _mlTarget);
      const id = res.id, realName = res.name;

      try {
        const sNow = OE.get();
        _oeMarkSaved(id, _oeOutfitSig(_oeWornIds(sNow.considering), { speciesId: sNow.speciesId, colorId: sNow.colorId, pose: sNow.pose, petStateId: sNow.petStateId, altStyleId: sNow.altStyleId, name: realName }));
      } catch (_) {}

      OE.set(s2 => {

        const _curV = (s2.variants || [])[_saveIdx];
        const _stillA = s2.activeIdx === _saveIdx;
        const _vSame = _curV && String(_curV.outfitId || '') === String(id) && (_curV.name || '') === (realName || '');
        const _fSame = !_stillA || (String(s2.outfitId || '') === String(id) && (s2.outfitName || '') === (realName || ''));
        if (_vSame && _fSame) return { lastSavedAt: Date.now() };
        const v = (s2.variants || []).map((x, i) => i === _saveIdx && x ? Object.assign({}, x, { outfitId: id, name: realName }) : x);
        const stillActive = s2.activeIdx === _saveIdx;
        return Object.assign({ variants: v, lastSavedAt: Date.now() },
          stillActive ? { outfitId: id, outfitName: realName } : {});
      });

      try {
        const _alp = OE.get().animLockPending;
        if (id && _alp != null) {
          const L = JSON.parse(window.dtrStore.get('dtr:settings:anim_locks', '{}')) || {};
          L[String(id)] = _alp ? 1 : 0;
          window.dtrStore.set('dtr:settings:anim_locks', JSON.stringify(L));
          OE.set({ animLockPending: null });
        }
      } catch (_) {}
      try { if (id) { if (_oeMyIds) _oeMyIds.add(String(id)); else _oeEnsureMyIds(); } } catch (_) {}
      try { _oeMarkSaved(id, _oeActiveSig(OE.get())); } catch (_) {}
      oeSaveTags(id, av.tags || []);
      oeSavePets(id, av.pets || null);
      oeSaveVariantGroup(oeAllOutfitIds(OE.get().variants));
      try { _oeSaveStarred(id, (OE.get().considering || []).filter(x => x && x.loved).map(x => x.id)); } catch (_) {}
      return id;
    }

    async function oeSaveVariantAt(idx) {
      const s = OE.get();
      const v = (s.variants || [])[idx];
      if (!v) return null;
      if (idx === s.activeIdx) {

        OE.set({ saveState: 'saving' });
        try {
          const id = await oeSaveOutfit();
          OE.set({ saveState: 'saved' });
          setTimeout(function () { try { if (OE.get().saveState === 'saved') OE.set({ saveState: 'idle' }); } catch (_) {} }, 1800);
          return id;
        } catch (e) {
          OE.set({ saveState: 'error' });
          setTimeout(function () { try { if (OE.get().saveState === 'error') OE.set({ saveState: 'idle' }); } catch (_) {} }, 3000);
          throw e;
        }
      }
      const b = v.biology || {};
      const bio = { species_id: b.speciesId, color_id: b.colorId, pose: OE_POSE_URLS[b.pose] || 'HAPPY_FEM', pet_state_id: b.petStateId || null, alt_style_id: b.altStyleId || null };

      const _vaWorn = _oeWornIds(v.items).length;
      const _vaAuth = v.outfitId != null ? _oeAuthCount[String(v.outfitId)] : null;
      if ((v.outfitId && _vaAuth != null && _vaWorn < _vaAuth && !_oeReachedFull[String(v.outfitId)])
          || (v.outfitId && _vaAuth == null && _vaWorn === 0)) {

        throw new Error('outfit-still-loading');
      }
      const res = await oeSaveOutfitData(v.name || 'My Outfit', _oeWornIds(v.items), _oeIsBorrowed(v.outfitId) ? null : (v.outfitId || null), bio);
      OE.set(s2 => { const vv = (s2.variants || []).slice(); if (vv[idx]) vv[idx] = Object.assign({}, vv[idx], { outfitId: res.id, name: res.name }); return { variants: vv, lastSavedAt: Date.now() }; });
      oeSaveTags(res.id, v.tags || []);
      oeSavePets(res.id, v.pets || null);
      oeSaveVariantGroup(oeAllOutfitIds(OE.get().variants));
      return res.id;
    }

