      pop.style.cssText = 'position:fixed;z-index:2147483300;display:flex;flex-direction:column;background:' + OE_IRID
        + ';border-radius:16px;box-shadow:0 16px 54px var(--dtr-scrim, rgba(40,35,30,.32));overflow:hidden;'
